use serde_json::{json,Value};
use std::{collections::{BTreeMap,BTreeSet},fs,path::Path};
fn load(p:impl AsRef<Path>)->Value {serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn report(x:&mut Value){for phase in x["phases"].as_array_mut().unwrap(){assert!(phase.as_object_mut().unwrap().remove("wall").is_some());}let stats=x["stats"].as_array_mut().unwrap();assert!(stats.iter().filter(|v|v[0]=="wall_total").count()<=1);stats.retain(|v|v[0]!="wall_total");}
fn arms(x:&mut Value){for arm in ["original","candidate"] {report(&mut x[arm]);}}
fn canonical(mut rows:Vec<Value>)->Vec<String>{for row in &mut rows {let kind=row["kind"].as_str().unwrap().to_owned();let x=&mut row["data"];match kind.as_str(){"N4_NEW_JACOBIAN_IC_ATTEMPT"=>report(&mut x["report"]),"N4_COMPLETED_ATTEMPT"=>{for arm in ["baseline","candidate"]{report(&mut x[arm]);}},"N4_PUBLIC_ATTEMPT"=>report(&mut x["public"]),"N4_ORIGIN_ATTEMPT"|"N4_NORM_SAMPLER_ATTEMPT"=>arms(x),"N4_ORIGIN_SCOPE"=>{for a in x["all_attempts"].as_array_mut().unwrap(){arms(a);}},_=>()}}let mut out:Vec<_>=rows.iter().map(|v|serde_json::to_string(v).unwrap()).collect();out.sort();out}
fn records(log:&str)->Vec<Value>{let mut rows=vec![];for line in log.lines(){if let Some(i)=line.find("N4_"){if let Some((kind,body))=line[i..].split_once(' '){if kind.bytes().all(|c|c.is_ascii_uppercase()||c.is_ascii_digit()||c==b'_')&&body.starts_with('{')&&body.ends_with('}'){rows.push(json!({"kind":kind,"data":serde_json::from_str::<Value>(body).unwrap()}));}}}}rows}
fn main(){let args:Vec<_>=std::env::args().collect();assert_eq!(args.len(),3);let p=Path::new(&args[1]);let golden=load(&args[2]);let digests=load(p.join("canonical-digests60.json"));assert_eq!(digests.as_object().unwrap().len(),60);let jobs=load(p.join("all-jobs.json"));let mapping:BTreeMap<_,_>=[("completed-descent","completed"),("completed-v2-rho","V2"),("public-target","P1"),("two-primary","two-primary"),("bitangents","bitangents"),("kernels","kernels"),("gluing","gluing"),("chain-kernels","chain"),("odd-source","odd"),("odd-product","product"),("odd-refinement","refinement"),("new-target-ic","newIC"),("common-origin","origin"),("norm-sampling","sampling")].into_iter().collect();let mut counts=BTreeMap::new();let mut verdicts=vec![];let mut skipped=0;let mut success=0;let mut distinct=BTreeSet::new();
for item in jobs.as_array().unwrap(){assert_eq!(item["run"]["status"],"completed");assert_eq!(item["run"]["conclusion"],"success");distinct.insert(item["run"]["workflow_id"].as_u64().unwrap());for job in item["api"]["structuredContent"]["jobs"].as_array().unwrap(){if job["name"]=="sign"{assert_eq!(job["conclusion"],"skipped");skipped+=1;continue;}assert_eq!(job["conclusion"],"success");let id=job["id"].as_u64().unwrap();let name=job["name"].as_str().unwrap();let log=fs::read_to_string(p.join(format!("whole-job-{id}.txt"))).unwrap();assert!(log.contains("398d591b0d6dbcab903a95e54c073b44de442ec3"));success+=1;if let Some(label)=mapping.get(name){let rows=records(&log);assert_eq!(canonical(rows.clone()),canonical(golden[*label].as_array().unwrap().clone()),"whole native JSON mismatch {label}");counts.insert(label.to_string(),rows.len());for line in log.lines(){if let Some(i)=line.find("{\"claim_id\":"){let v:Value=serde_json::from_str(&line[i..]).unwrap();assert_eq!(v["verdict"],"pass");assert!(v["reasons"].as_array().unwrap().is_empty());assert_eq!(v["commit"],"398d591b0d6dbcab903a95e54c073b44de442ec3");let claim=v["claim_id"].as_str().unwrap();assert_eq!(v["claim_sha256"],digests[claim]);verdicts.push(v);}}}else if name=="arithmetic-audit"{let rows=records(&log);let sampler=rows.iter().filter(|v|v["kind"].as_str().unwrap().starts_with("N4_NORM_SAMPLER_")).cloned().collect::<Vec<_>>();assert_eq!(sampler.len(),86);assert_eq!(canonical(sampler),canonical(golden["sampling"].as_array().unwrap().clone()));let census=rows.iter().filter(|v|v["kind"]=="N4_ARITHMETIC_CENSUS").collect::<Vec<_>>();assert_eq!(census.len(),1);let expected=load(p.join("arithmetic-artifact-members/n4-arithmetic-output/expected-census.json"));assert_eq!(census[0]["data"],expected,"whole census and all metadata, NO masks");assert_eq!(expected["rows"].as_array().unwrap().len(),7113);assert!(log.contains("test result: ok. 1 passed; 0 failed; 0 ignored; 0 measured; 0 filtered out;"));counts.insert("arithmetic-sampler".into(),86);}else {assert!(["gate","original-fixture","original-checkpoint"].contains(&name),"unexpected job {name}");}}}
assert_eq!(distinct.len(),18);assert_eq!(success,19);assert_eq!(skipped,2);assert_eq!(counts.values().sum::<usize>(),413);assert_eq!(verdicts.len(),62);let mut reuse=BTreeMap::<String,usize>::new();for v in &verdicts{*reuse.entry(v["claim_id"].as_str().unwrap().to_owned()).or_default()+=1;}assert_eq!(reuse.len(),60);let repeated:Vec<_>=reuse.iter().filter(|(_,n)|**n!=1).map(|(k,n)|(k.as_str(),*n)).collect();assert_eq!(repeated,vec![("PCC-20261113-01efbf",2),("PCC-20261113-671d42",2)]);
let a=p.join("arithmetic-artifact-members/n4-arithmetic-output");let names=["materialize","fetch-original","lock-solver","fetch-taps","lock-taps","frozen-registry","compile","native","ledger-unit","compare-build","all86","census-build","census","omitted-hook-canaries","derived-guards"];assert_eq!(fs::read_to_string(a.join("phases.txt")).unwrap(),names.iter().map(|x|format!("{x} 0\n")).collect::<String>());for n in names{assert_eq!(fs::read_to_string(a.join(format!("{n}.pipe-exits"))).unwrap(),"0 0\n");}for n in ["original","phase-caller","final-audit-source","final-original-785","final-derived"]{assert_eq!(fs::read_to_string(a.join(format!("{n}.exit"))).unwrap(),"0\n");}
let out=json!({"source":"398d591b0d6dbcab903a95e54c073b44de442ec3","distinct_workflows":18,"actual_successful_event_runs":19,"automatic_extra_PCC_body_event":true,"PCC_sign_jobs_skipped":2,"whole_native_records":413,"per_workflow_native_counts":counts,"old327_plus_arithmetic86_exact":true,"only_previously_frozen_wall_masks":true,"whole_arithmetic_census7113_and_all_metadata_exact_no_masks":true,"all15_phase_native_tee_pairs":[0,0],"all_final_source_original_derived_guards":0,"canonical_original_PCC_digests":60,"actual_verdicts":62,"reused_original_twice":["01efbf","671d42"],"scope":"unsigned data; no execution standing or performance inference"});fs::write(p.join("audit-result.json"),serde_json::to_vec_pretty(&out).unwrap()).unwrap();fs::write(p.join("all62-current-verdicts.json"),serde_json::to_vec(&verdicts).unwrap()).unwrap();println!("ALL18 distinct workflows/19 automatic runs successful; ALL413 whole native rows exact under frozen walls; whole7113census+metadata exact/no masks;15phasepairs0/0;60canonicaldigests/62verdicts; final guards0.");}
